$ErrorActionPreference = 'Continue';
New-Item -ItemType Directory -Force -Path 'C:\ProgramData\LSW\logs' | Out-Null;
$log = 'C:\ProgramData\LSW\logs\promote.log';
function Roll-Log([string] $LogFile) {
    try {
        if ((Test-Path -LiteralPath $LogFile) -and (Get-Item -LiteralPath $LogFile).Length -gt 2MB) {
            $stem = $LogFile.Substring(0, $LogFile.Length - 4)
            Remove-Item -LiteralPath ($stem + '.2.log') -Force -ErrorAction SilentlyContinue
            if (Test-Path -LiteralPath ($stem + '.1.log')) {
                Move-Item -LiteralPath ($stem + '.1.log') -Destination ($stem + '.2.log') -Force
            }
            Move-Item -LiteralPath $LogFile -Destination ($stem + '.1.log') -Force
        }
    } catch { }
}
Roll-Log $log;
function L($m) { ('{0} {1}' -f (Get-Date -Format s), $m) | Add-Content -LiteralPath $log -Encoding Ascii; }
$releaseId = '{{release}}';
$bundleVersion = '{{version}}';
$payload = [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'CDRom' -and $_.IsReady -and $_.VolumeLabel -eq 'LSW_PAYLOAD' } | Select-Object -First 1;
if (-not $payload) {
    L 'no LSW_PAYLOAD volume - nothing to update from';
} else {
    $stageDir = 'C:\ProgramData\LSW\update\' + $releaseId.Substring(0, 16);
    Remove-Item -LiteralPath $stageDir -Recurse -Force -ErrorAction SilentlyContinue;
    $out = & xcopy.exe ($payload.RootDirectory.FullName + 'update') $stageDir /E /I /Y /Q 2>&1 | Out-String;
    L ('xcopy of ' + $payload.RootDirectory.FullName + 'update to ' + $stageDir + ' exited ' + $LASTEXITCODE + ': ' + $out.Trim());
    $updateScript = $stageDir + '\C\ProgramData\LSW\lsw-guest-update.ps1';
    if (-not (Test-Path -LiteralPath $updateScript)) {
        L ($updateScript + ' missing - the payload carried no update');
    } else {
        $out = & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $updateScript -Stage $stageDir -Release $releaseId -Version $bundleVersion -NoRestart 2>&1 | Out-String;
        L ('lsw-guest-update.ps1 exited ' + $LASTEXITCODE + ' - see update.log');
        if ($out) { $out.TrimEnd() | Add-Content -LiteralPath $log -Encoding Ascii; }
    }
}
$flag = 'C:\ProgramData\LSW\promoted.flag';
if (Test-Path -LiteralPath $flag) { L 'promoted.flag present - skipping'; exit 0; }
$u = '{{user_name}}';
L ('SetupComplete promote start; target=' + $u + '; ctx=' + [System.Security.Principal.WindowsIdentity]::GetCurrent().Name);
$lu = $null; $n = 0;
while ($n -lt 60) {
    $lu = Get-LocalUser -Name $u -ErrorAction SilentlyContinue;
    if ($lu) { break; }
    Start-Sleep -Seconds 5; $n++;
}
if (-not $lu) { L 'account never materialized after 5 min - giving up'; exit 0; }
$members = @( Get-LocalGroupMember -Group 'Administrators' -ErrorAction SilentlyContinue | ForEach-Object { $_.SID.Value } );
if ($members -contains $lu.SID.Value) {
    L ('already a member: ' + $u);
} else {
    try {
        Add-LocalGroupMember -Group 'Administrators' -Member $lu -ErrorAction Stop;
        L ('ADDED ' + $u + ' to local Administrators');
    } catch {
        L ('Add-LocalGroupMember FAILED: ' + $_.Exception.Message);
        exit 0;
    }
}
Set-Content -LiteralPath $flag -Value (Get-Date -Format s) -Encoding Ascii -Force;
( Get-LocalGroupMember -Group 'Administrators' | Format-Table Name, SID -AutoSize | Out-String ) | Add-Content -LiteralPath $log -Encoding Ascii;
L 'SetupComplete promote done';
